examples.setupTemplate:
var items by remember {
    mutableStateOf(
        listOf(
            MonarchUploadQueueItem(id = {{items.0.id}}, name = {{items.0.name}}, status = MonarchUploadStatus.{{items.0.status|pascal}}, size = {{items.0.size}}),
            MonarchUploadQueueItem(id = {{items.1.id}}, name = {{items.1.name}}, status = MonarchUploadStatus.{{items.1.status|pascal}}, size = {{items.1.size}}, progress = ({{items.1.progress|double}} / 100).toFloat()),
            MonarchUploadQueueItem(id = {{items.2.id}}, name = {{items.2.name}}, status = MonarchUploadStatus.{{items.2.status|pascal}}, size = {{items.2.size}}),
            MonarchUploadQueueItem(id = {{items.3.id}}, name = {{items.3.name}}, status = MonarchUploadStatus.{{items.3.status|pascal}}, size = {{items.3.size}}, errorMessage = {{items.3.error}}),
            MonarchUploadQueueItem(id = {{items.4.id}}, name = {{items.4.name}}, status = MonarchUploadStatus.{{items.4.status|pascal}}, size = {{items.4.size}}, errorMessage = {{items.4.error}}, retryable = {{items.4.retryable}}),
        ),
    )
}

